const d = $input.first().json;
const m = d.metricas;
const periodo = `${d.periodo?.inicio} a ${d.periodo?.fim}`;

// Funil como texto
const funilTexto = (d.funil ?? [])
  .map(e => `${e.etapa}: ${e.total}`)
  .join('\n');

// Ranking
const rankingTexto = (d.ranking_comercial ?? [])
  .map((r, i) => `${i+1}. ${r.nome} — ${r.total} fechamento(s)`)
  .join('\n');

// HTML para e-mail
const html = `
<html><body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
<h2 style="color: #1e40af;">📊 Relatório Semanal CRM Jurídico</h2>
<p style="color: #6b7280;">Período: ${periodo}</p>

<table style="width:100%;border-collapse:collapse;margin:16px 0;">
  <tr style="background:#eff6ff;"><th colspan="2" style="padding:10px;text-align:left;border-bottom:2px solid #1e40af;">Resumo da Semana</th></tr>
  <tr><td style="padding:8px;border-bottom:1px solid #e5e7eb;">🆕 Leads criados</td><td style="padding:8px;border-bottom:1px solid #e5e7eb;font-weight:bold;">${m.leads_criados}</td></tr>
  <tr><td style="padding:8px;border-bottom:1px solid #e5e7eb;">📅 Reuniões realizadas</td><td style="padding:8px;border-bottom:1px solid #e5e7eb;font-weight:bold;">${m.reunioes_realizadas}</td></tr>
  <tr><td style="padding:8px;border-bottom:1px solid #e5e7eb;">📝 Contratos assinados</td><td style="padding:8px;border-bottom:1px solid #e5e7eb;font-weight:bold;">${m.contratos_assinados}</td></tr>
  <tr><td style="padding:8px;border-bottom:1px solid #e5e7eb;">✅ Tarefas concluídas</td><td style="padding:8px;border-bottom:1px solid #e5e7eb;font-weight:bold;">${m.tarefas_concluidas}</td></tr>
  <tr><td style="padding:8px;">💰 Receita confirmada</td><td style="padding:8px;font-weight:bold;color:#16a34a;">R$ ${m.receita_semana?.toFixed(2)}</td></tr>
</table>

<h3 style="color:#1e40af;">🏆 Ranking Comercial</h3>
<pre style="background:#f9fafb;padding:12px;border-radius:8px;">${rankingTexto || 'Nenhum fechamento esta semana'}</pre>

<h3 style="color:#1e40af;">📈 Funil Atual</h3>
<pre style="background:#f9fafb;padding:12px;border-radius:8px;">${funilTexto || 'Sem dados'}</pre>

<h3 style="color:#1e40af;">🔔 Estado Atual do CRM</h3>
<table style="width:100%;border-collapse:collapse;">
  <tr><td style="padding:6px;border-bottom:1px solid #e5e7eb;">Onboardings ativos</td><td style="padding:6px;border-bottom:1px solid #e5e7eb;font-weight:bold;">${d.estado_atual?.onboardings_ativos ?? 0}</td></tr>
  <tr><td style="padding:6px;border-bottom:1px solid #e5e7eb;">Cobranças pendentes</td><td style="padding:6px;border-bottom:1px solid #e5e7eb;font-weight:bold;">${d.estado_atual?.cobracas_pendentes ?? 0}</td></tr>
  <tr><td style="padding:6px;">Tarefas vencidas</td><td style="padding:6px;font-weight:bold;color:#dc2626;">${d.estado_atual?.tarefas_vencidas ?? 0}</td></tr>
</table>

<p style="color:#9ca3af;font-size:12px;margin-top:24px;">Gerado automaticamente pelo CRM Jurídico em ${new Date(d.gerado_em).toLocaleString('pt-BR')}</p>
</body></html>`;

// Texto para WhatsApp
const whatsapp = `📊 *Relatório Semanal — ${periodo}*\n\n` +
  `🆕 Leads criados: *${m.leads_criados}*\n` +
  `📅 Reuniões realizadas: *${m.reunioes_realizadas}*\n` +
  `📝 Contratos assinados: *${m.contratos_assinados}*\n` +
  `💰 Receita: *R$ ${m.receita_semana?.toFixed(2)}*\n\n` +
  `🏆 Top vendedor: *${d.ranking_comercial?.[0]?.nome ?? 'N/A'}*\n\n` +
  `⚠️ Tarefas vencidas: *${d.estado_atual?.tarefas_vencidas ?? 0}*`;

return [{ json: { html, whatsapp, periodo, metricas: m } }];
